import{_ as o,C as i,o as r,c as n,j as a,a as t,E as l,ak as d}from"./chunks/framework.BlXg7nwm.js";const x=JSON.parse('{"title":"Variables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notation/variables.md","filePath":"guide/notation/variables.md","lastUpdated":1795178666000}'),c={name:"guide/notation/variables.md"},u={id:"variables",tabindex:"-1"};function p(b,e,h,v,m,f){const s=i("Badge");return r(),n("div",null,[a("h1",u,[e[0]||(e[0]=t("Variables ",-1)),l(s,{text:"New in v6",vertical:"middle"}),e[1]||(e[1]=t()),e[2]||(e[2]=a("a",{class:"header-anchor",href:"#variables","aria-label":'Permalink to "Variables <Badge text="New in v6" vertical="middle"/>"'},"​",-1))]),e[3]||(e[3]=d('<p>Variables let you reuse the same notation with different values, such as each character&#39;s attack bonus.</p><p>You can <a href="#variables-you-supply">supply your own values</a> when you make a roll, or use the <a href="#built-in-variables">built-in variables</a>.</p><h2 id="variables-you-supply" tabindex="-1">Variables you supply <a class="header-anchor" href="#variables-you-supply" aria-label="Permalink to &quot;Variables you supply&quot;">​</a></h2><p>Put <code>$</code> before a variable name in the notation. For example, <code>d20 + $bonus</code> adds the value of <code>bonus</code> to a d20 roll. Use a dot to refer to a value inside a nested object, as in <code>$character.attackBonus</code>.</p><p>A variable name must start with an upper- or lowercase letter or an underscore. After that, you can use letters, numbers or underscores. The same rules apply to each name in a dotted reference. Capitalisation matters.</p><p>A variable’s value must be a finite number or a boolean (<code>true</code> or <code>false</code>). In expressions, <code>true</code> becomes <code>1</code> and <code>false</code> becomes <code>0</code>.</p><p>If the dice roller evaluates a reference and its value is missing, the roll throws an error. It skips lookups in the unselected branch of a ternary.</p><p>See <a href="./../usage/#variable-data">Variable data</a> for how to pass these values to a roll.</p><h2 id="using-variables-in-expressions" tabindex="-1">Using variables in expressions <a class="header-anchor" href="#using-variables-in-expressions" aria-label="Permalink to &quot;Using variables in expressions&quot;">​</a></h2><p>You can use variables in arithmetic, functions, comparisons and ternaries, as well as in <a href="./maths.html#calculating-quantities-and-sides">calculated quantities and sides</a>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(max($skill + $attribute, 4))d10</span></span></code></pre></div><p>With <code>$skill</code> set to <code>3</code> and <code>$attribute</code> set to <code>2</code>, <code>max(3 + 2, 4)</code> gives <code>5</code>, so the notation rolls <code>5d10</code>.</p><h2 id="built-in-variables" tabindex="-1">Built-in variables <a class="header-anchor" href="#built-in-variables" aria-label="Permalink to &quot;Built-in variables&quot;">​</a></h2><p>The dice roller sets built-in variables as it evaluates the notation. Use <code>$$</code> before the variable name to reference them.</p><p>Inside the selected branch of a ternary, <code>$$condition</code> holds the numeric result of the condition. See <a href="./../usage/#built-in-variables">Built-in variables in the usage guide</a> for a worked example.</p>',15))])}const y=o(c,[["render",p]]);export{x as __pageData,y as default};
